std::vector<element_type> container_name; // Declaration
container_name.push_back(element); // Adding elements
container_name.begin(), container_name.end(); // Iterators for algorithms
// Modern usage includes range-based for loops: for (auto& element : container_name) { ... }

code_example:
#include <iostream>
#include <vector>
#include <algorithm>
int main() {
    // Create a vector of integers using modern C++ initialization
    std::vector<int> numbers = {5, 3, 8, 1, 4};
    // Add an element using move semantics (C++11 feature)
    int new_value = 10;
    numbers.push_back(std::move(new_value));
    // Sort the vector using STL algorithm
    std::sort(numbers.begin(), numbers.end());
    // Use range-based for loop for iteration
    for (const auto& num : numbers) {
        std::cout << num << ' ';
    }
    std::cout << std::endl;
    return 0;
}
